// This spec uses the packaged Workbench and a real RDF4J repository, not a GraphServlet stand-in.
const REPOSITORY_ID = process.env.RDF4J_GRAPH_LIVE_REPOSITORY_ID || uniqueRepositoryId('graph-fixed-bnodes-live');
const REPOSITORY_URL = `${serverBaseUrl()}/repositories/${encodeURIComponent(REPOSITORY_ID)}`;
const EVIDENCE_DIRECTORY = path.join(
	process.env.RDF4J_GRAPH_LIVE_EVIDENCE_DIR || '/tmp/rdf4j-graph-fixed-bnodes-live', REPOSITORY_ID);
const NS = 'urn:rdf4j:fixed-bnodes-live:';
const RDF = 'http://www.w3.org/1999/02/22-rdf-syntax-ns#';
const RDFS = 'http://www.w3.org/2000/01/rdf-schema#';
const DOCUMENT = `${NS}document`;
function fixtureData() {
	const lines = [
		`@prefix ex: <${NS}> .`,
		`@prefix rdf: <${RDF}> .`,
		`@prefix rdfs: <${RDFS}> .`,
		'ex:anchor ex:alice _:alice ; ex:bob _:bob .',
		'_:alice a ex:Person ; rdfs:label "Alice" ; ex:knows _:bob ; ex:note "Literal control"@en .',
		'_:bob a ex:Person ; rdfs:label "Bob" ; ex:worksFor ex:organization .',
		'ex:organization rdfs:label "Organization" .',
		`<${DOCUMENT}> rdfs:label "Document" ; ex:mentions _:alice .`,
		'_:reifier a rdf:Statement ; rdf:subject _:alice ; rdf:predicate ex:knows ; rdf:object _:bob ; ex:confidence "0.98" .'
	];
	for (let index = 0; index < 90; index++) {
		const outgoing = index % 2 === 0 ? `_:outBlank${index}` : `<${NS}outIri${index}>`;
		const incoming = index % 2 === 0 ? `_:inBlank${index}` : `<${NS}inIri${index}>`;
		const outgoingKind = index % 2 === 0 ? 'blank' : 'IRI';
		const incomingKind = index % 2 === 0 ? 'blank' : 'IRI';
		lines.push(`_:alice ex:outgoingNeighbor ${outgoing} .`);
		lines.push(`${outgoing} rdfs:label "Outgoing ${outgoingKind} ${index}" .`);
		lines.push(`${incoming} ex:incomingNeighbor _:alice .`);
		lines.push(`${incoming} rdfs:label "Incoming ${incomingKind} ${index}" .`);
	}
	lines.push(
		'_:blankGraph {',
		'  _:alice a ex:Person ; rdfs:label "Alice" ; ex:blankGraphMarker "blank graph scope" ; ex:knows _:bob .',
		'  _:bob a ex:Person ; rdfs:label "Bob" .',
		'}',
		`<${NS}iriGraph> { _:alice ex:iriGraphMarker "IRI graph scope" . }`
	);
	return `${lines.join('\n')}\n`;
}

let fixtureCreated = false;
let alice;
let bob;
let blankGraph;

test.describe.configure({ mode: 'serial' });
test.setTimeout(120000);

async function queryStoredBlankNode(request, query) {
	const response = await request.post(repositoryPageUrl(REPOSITORY_ID, 'graph'), {
		headers: {
			Accept: 'application/sparql-results+json',
			'Content-Type': 'application/sparql-query'
		},
		data: query
	});
	if (response.status() !== 200) {
		throw new Error(`SELECT failed with HTTP ${response.status()}: ${await response.text()}`);
	}
	const identity = response.headers()['x-workbench-server-identity'];
	expect(identity).toBeTruthy();
	const json = await response.json();
	const term = json.results?.bindings?.[0]?.node;
	expect(term?.type).toBe('bnode');
	expect(term?.['rdf4j:reference']).toBe(true);
	return { raw: term.value, reference: fixedBlankNodeReference(term.value), serverIdentity: identity };
}

test.beforeAll(async ({ request }) => {
	const existing = await request.get(`${REPOSITORY_URL}/config`);
	if (existing.status() !== 404) {
		throw new Error(`Refusing to use non-absent live test repository ${REPOSITORY_ID}: GET config ${existing.status()}`);
	}
	const created = await request.put(REPOSITORY_URL, {
		headers: { 'Content-Type': 'text/turtle' },
		data: memoryRepositoryConfiguration(REPOSITORY_ID, 'Live fixed blank node interaction fixture')
	});
	if (![200, 201, 204].includes(created.status())) {
		throw new Error(`Creating live test repository failed with HTTP ${created.status()}`);
	}
	fixtureCreated = true;
	const loaded = await request.post(`${REPOSITORY_URL}/statements`, {
		headers: { 'Content-Type': 'application/trig' },
		data: fixtureData()
	});
	if (![200, 204].includes(loaded.status())) {
		throw new Error(`Loading live test data failed with HTTP ${loaded.status()}: ${await loaded.text()}`);
	}
	alice = await queryStoredBlankNode(request, `SELECT ?node WHERE { <${NS}anchor> <${NS}alice> ?node }`);
	bob = await queryStoredBlankNode(request, `SELECT ?node WHERE { <${NS}anchor> <${NS}bob> ?node }`);
	blankGraph = await queryStoredBlankNode(request,
		`SELECT ?node WHERE { GRAPH ?node { ?subject <${NS}blankGraphMarker> ?marker } }`);
	expect(alice.raw).not.toBe(bob.raw);
	expect(alice.raw).not.toBe(blankGraph.raw);
	fs.mkdirSync(EVIDENCE_DIRECTORY, { recursive: true });
	fs.writeFileSync(path.join(EVIDENCE_DIRECTORY, 'fixture-identities.json'), JSON.stringify({
		repositoryId: REPOSITORY_ID,
		repositoryUrl: REPOSITORY_URL,
		workbenchUrl: workbenchBaseUrl(),
		serverIdentity: alice.serverIdentity,
		blankNodes: { alice, bob, blankGraph }
	}, null, 2));
	console.info(`Live graph fixture: ${REPOSITORY_URL}; Alice=${alice.reference}; Bob=${bob.reference}; blank graph=${blankGraph.reference}`);
});

test.afterAll(async ({ request }) => {
	if (!fixtureCreated) {
		return;
	}
	if (process.env.RDF4J_GRAPH_PRESERVE_REPOSITORY === 'true') {
		const retained = await request.get(`${REPOSITORY_URL}/config`);
		if (retained.status() !== 200) {
			throw new Error(`Preserved repository ${REPOSITORY_ID} is unavailable: GET config ${retained.status()}`);
		}
		console.info(`Preserved live graph fixture for independent review: ${REPOSITORY_URL}`);
		return;
	}
	await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

function graphTraffic(page) {
	const traffic = { queries: [], responses: [] };
	page.on('request', request => {
		const url = new URL(request.url());
		if (request.method() === 'POST' && url.pathname.endsWith('/graph')) {
			traffic.queries.push(request.postData() || '');
		}
	});
	page.on('response', response => {
		const url = new URL(response.url());
		if (url.pathname.endsWith('/graph')) {
			response.headerValue('x-workbench-server-identity').then(identity => {
				traffic.responses.push({ status: response.status(), identity });
			});
		}
	});
	return traffic;
}

async function installClipboardRecorder(page) {
	const writes = [];
	await page.exposeFunction('__recordFixedBNodeClipboardWrite', value => writes.push(value));
	await page.addInitScript(() => {
		Object.defineProperty(navigator, 'clipboard', {
			configurable: true,
			value: { writeText: value => window.__recordFixedBNodeClipboardWrite(value) }
		});
	});
	return writes;
}

async function openGraphPage(page, viewport = { width: 1440, height: 900 }) {
	await page.setViewportSize(viewport);
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'graph'), { waitUntil: 'domcontentloaded' });
	await waitForRoute(page, 'graph');
	return page.locator('.graph-explorer');
}

async function addFromExplore(page, resourceReference) {
	await page.goto(`${repositoryPageUrl(REPOSITORY_ID, 'explore')}?resource=${encodeURIComponent(resourceReference)}`,
		{ waitUntil: 'domcontentloaded' });
	await waitForRoute(page, 'explore');
	await expect(page.locator('#explore-resource-card')).toBeVisible();
	await page.getByRole('button', { name: 'Add to graph' }).first().click();
	await expect(page.getByRole('link', { name: 'Open graph' })).toBeVisible();
}

function graphNode(graph, kind, label) {
	return graph.locator(`.graph-node.${kind}`).filter({ hasText: label }).first();
}

async function graphDiagnosticSnapshot(page) {
	return page.evaluate(() => ({
		visibilityState: document.visibilityState,
		focused: document.hasFocus(),
		status: document.querySelector('.status-text')?.textContent || '',
		stats: document.querySelector('.graph-stats')?.textContent || null,
		nodeTitles: [...document.querySelectorAll('.graph-node > title')].map(node => node.textContent),
		expandingNodeTitles: [...document.querySelectorAll('.graph-node.is-expanding > title')].map(node => node.textContent),
		moreBadges: [...document.querySelectorAll('.node-more text')].map(node => node.textContent),
		visibilityEvents: window.__fixedBNodeVisibilityEvents || []
	}));
}

async function setGraphScope(page, scope) {
	await page.getByRole('button', { name: 'Query editor', exact: true }).click();
	const preferences = page.locator('.label-preferences');
	await expect(preferences).toBeVisible();
	await preferences.locator('summary').click();
	await preferences.getByLabel('Graphs to explore').selectOption(scope === 'named' ? 'named' : scope);
	if (scope === 'named') {
		await preferences.getByLabel('Named graph IRI').fill(blankGraph.reference);
		await preferences.getByRole('button', { name: 'Use graph' }).click();
	}
	await page.getByRole('button', { name: 'Close query editor' }).click();
}

async function findStoredAlice(page, traffic) {
	const find = page.getByRole('combobox', { name: 'Find a node, or search the repository' });
	await find.fill(alice.reference);
	const search = page.getByRole('option', { name: /Search the repository for/ });
	await expect(search).toBeVisible();
	await search.click();
	const graph = page.locator('.graph-explorer');
	await expect(graphNode(graph, 'blank', 'Alice')).toBeAttached({ timeout: 30000 });
	await expect.poll(() => traffic.queries.some(query =>
		query.includes(`VALUES ?source { ${alice.reference} }`))).toBe(true);
}

async function applyBlankBobFacet(page, traffic, scope) {
	await page.getByRole('button', { name: /Filter graph nodes/ }).click();
	const panel = page.locator('#graph-filter-sidebar');
	await expect(panel).toBeVisible();
	const moreFilters = panel.getByRole('button', { name: /more filters/ });
	if (await moreFilters.count()) {
		await moreFilters.click();
	}
	const relation = panel.locator('.filter-facet').filter({ hasText: 'knows' }).first();
	if (!(await relation.getAttribute('open'))) {
		await relation.locator('summary').click();
	}
	const value = relation.locator('.facet-value').filter({ hasText: 'Bob' }).first();
	await expect(value).toBeVisible();
	const priorQueryCount = traffic.queries.length;
	await value.click();
	const queryWorkspace = page.locator('#query-workspace');
	if (!(await queryWorkspace.isVisible())) {
		await page.getByRole('button', { name: 'Query editor', exact: true }).click();
	}
	await queryWorkspace.locator('.visual-query summary').click();
	await queryWorkspace.getByRole('button', { name: 'Copy to the editor' }).click();
	const query = await queryWorkspace.locator('textarea#sparql').inputValue();
	expect(query).toContain(bob.reference);
	expect(query).toContain('SELECT DISTINCT ?source ?predicate ?target');
	if (scope === 'all') {
		expect(query).toContain('UNION');
	} else if (scope === 'named') {
		expect(query).toContain(`GRAPH ${blankGraph.reference}`);
	} else {
		expect(query).not.toContain('GRAPH ');
	}
	await queryWorkspace.getByRole('button', { name: 'Run query' }).click();
	await expect.poll(() => traffic.queries.slice(priorQueryCount).some(candidate => candidate === query)).toBe(true);
}

test('stored blank nodes cross from Explore into another Graph tab and retain inspector actions responsively', async ({ context }) => {
	const graphPage = await context.newPage();
	const clipboardWrites = await installClipboardRecorder(graphPage);
	const traffic = graphTraffic(graphPage);
	const graph = await openGraphPage(graphPage);
	await expect(graph.locator('.empty-state h3')).toHaveText('The graph is empty');

	const explorePage = await context.newPage();
	await addFromExplore(explorePage, alice.reference);
	const aliceNode = graphNode(graph, 'blank', 'Alice');
	await expect(aliceNode).toBeAttached({ timeout: 30000 });
	await aliceNode.click();
	const details = graphPage.locator('.node-details');
	await expect(details).toBeVisible();
	await expect(details.getByRole('button', { name: 'Expand', exact: true })).toBeVisible();
	const explore = details.getByRole('link', { name: 'Explore', exact: true });
	await expect(explore).toBeVisible();
	const exploreUrl = new URL(await explore.getAttribute('href'), workbenchBaseUrl());
	expect(exploreUrl.searchParams.get('resource')).toBe(alice.reference);
	await details.getByRole('button', { name: 'Copy identifier' }).click();
	await expect.poll(() => clipboardWrites).toEqual([alice.reference]);
	await expect(details).toContainText('Literal control');
	await expect(details.locator('.is-incoming').first()).toBeVisible();
	fs.mkdirSync(EVIDENCE_DIRECTORY, { recursive: true });
	await graphPage.screenshot({ path: path.join(EVIDENCE_DIRECTORY, 'stored-blank-node-inspector-desktop.png'), fullPage: true });

	await graphPage.setViewportSize({ width: 390, height: 844 });
	await aliceNode.click();
	await expect(details).toBeVisible();
	await details.getByRole('button', { name: 'Close details' }).click();
	await aliceNode.click();
	await expect(details).toBeVisible();
	await expect(details.getByRole('link', { name: 'Explore', exact: true })).toBeVisible();
	await graphPage.screenshot({ path: path.join(EVIDENCE_DIRECTORY, 'stored-blank-node-inspector-mobile.png'), fullPage: true });

	await expect.poll(() => traffic.responses.length).toBeGreaterThan(0);
	expect(traffic.responses.every(response => response.status === 200 && response.identity)).toBe(true);
});

test('a compact stored blank-node graph renders Alice inspector screenshots on desktop and mobile', async ({ page }) => {
	const emptyGraph = await openGraphPage(page);
	await expect(emptyGraph.locator('.graph-node')).toHaveCount(0);
	await openQueryPage(page, REPOSITORY_ID);
	const query = `CONSTRUCT { ?s ?p ?o } WHERE { VALUES (?s ?p ?o) {
		(${alice.reference} <${NS}knows> ${bob.reference})
		(<${DOCUMENT}> <${NS}mentions> ${alice.reference})
	} }`;
	await runQuery(page, query);
	await page.getByRole('button', { name: 'Add the results to the graph' }).click();
	await expect(page.locator('.query-result-add-to-graph')).toContainText('Added to graph');
	const graph = await openGraphPage(page);
	await expect(graph.locator('.graph-node')).toHaveCount(3, { timeout: 30000 });
	await expect(graph.locator('.graph-node.blank')).toHaveCount(2);
	await expect(graph.locator('.graph-node.iri')).toHaveCount(1);
	const aliceNode = graphNode(graph, 'blank', 'Alice');
	await expect(aliceNode).toBeAttached();
	await expect(graphNode(graph, 'blank', 'Bob')).toBeAttached();
	await expect(graphNode(graph, 'iri', 'Document')).toBeAttached();
	await aliceNode.click();
	const details = page.locator('.node-details');
	await expect(details).toBeVisible();
	await expect(details).not.toHaveClass(/is-arriving/);
	await expect(details.getByRole('link', { name: 'Explore', exact: true })).toBeVisible();
	fs.mkdirSync(EVIDENCE_DIRECTORY, { recursive: true });
	await page.screenshot({ path: path.join(EVIDENCE_DIRECTORY, 'stored-three-node-inspector-desktop.png'), fullPage: true });

	await page.setViewportSize({ width: 390, height: 844 });
	await expect(details).toBeVisible();
	await expect(details).not.toHaveClass(/is-arriving/);
	await expect(details.getByRole('link', { name: 'Explore', exact: true })).toBeVisible();
	await page.screenshot({ path: path.join(EVIDENCE_DIRECTORY, 'stored-three-node-inspector-mobile.png'), fullPage: true });
});

for (const scope of ['default', 'all', 'named']) {
	test(`canonical Find and a selected blank facet execute in ${scope} graph scope`, async ({ page }) => {
		const traffic = graphTraffic(page);
		await openGraphPage(page);
		if (scope !== 'default') {
			await setGraphScope(page, scope);
		}
		await findStoredAlice(page, traffic);
		await applyBlankBobFacet(page, traffic, scope);
		await expect.poll(() => traffic.responses.length).toBeGreaterThan(0);
		expect(traffic.responses.every(response => response.status === 200 && response.identity)).toBe(true);
	});
}

test('mixed blank and IRI selections query together and paged expansion yields every unique neighbor', async ({ page }) => {
	const graphPage = page;
	const traffic = graphTraffic(graphPage);
	await graphPage.addInitScript(() => {
		window.__fixedBNodeVisibilityEvents = [];
		const record = type => window.__fixedBNodeVisibilityEvents.push({
			type,
			state: document.visibilityState,
			focused: document.hasFocus(),
			time: Math.round(performance.now())
		});
		document.addEventListener('visibilitychange', () => record('visibilitychange'));
		window.addEventListener('focus', () => record('focus'));
		window.addEventListener('blur', () => record('blur'));
		window.addEventListener('pageshow', () => record('pageshow'));
		window.addEventListener('pagehide', () => record('pagehide'));
		record('init');
	});
	const graph = await openGraphPage(graphPage);
	const explorePage = await graphPage.context().newPage();
	await addFromExplore(explorePage, alice.reference);
	await graphPage.bringToFront();
	await expect.poll(() => graphPage.evaluate(() => document.visibilityState), { timeout: 15000 }).toBe('visible');
	try {
		await expect.poll(async () => (await graphDiagnosticSnapshot(graphPage)).status, { timeout: 15000 })
			.toMatch(/^(Added \d+ statements?\.|Already in the graph\.|Nothing to add: .+)$/);
	} catch (error) {
		const snapshot = await graphDiagnosticSnapshot(graphPage);
		fs.mkdirSync(EVIDENCE_DIRECTORY, { recursive: true });
		fs.writeFileSync(path.join(EVIDENCE_DIRECTORY, 'cross-tab-add-settlement.json'), JSON.stringify(snapshot, null, 2));
		console.error(`Cross-tab Add-to-graph did not settle: ${JSON.stringify(snapshot)}`);
		throw error;
	}
	const importSettled = await graphDiagnosticSnapshot(graphPage);
	fs.mkdirSync(EVIDENCE_DIRECTORY, { recursive: true });
	fs.writeFileSync(path.join(EVIDENCE_DIRECTORY, 'cross-tab-add-settlement.json'), JSON.stringify(importSettled, null, 2));
	const aliceNode = graphNode(graph, 'blank', 'Alice');
	await expect(aliceNode).toBeAttached({ timeout: 30000 });
	await expect(aliceNode.locator('.node-more')).toBeAttached({ timeout: 30000 });
	let pageNumber = 0;
	while (await aliceNode.locator('.node-more').count()) {
		pageNumber += 1;
		const badge = aliceNode.locator('.node-more').first();
		const before = await badge.textContent();
		const beforeStats = await graph.locator('.graph-stats').textContent();
		const queryCountBefore = traffic.queries.length;
		const beforeSnapshot = await graphDiagnosticSnapshot(graphPage);
		const evidenceStem = pageNumber === 1 ? 'first-expansion' : `expansion-${pageNumber}`;
		let expansionEvidence = { pageNumber, before, beforeStats, beforeSnapshot };
		let request = null;
		let response = null;
		let responseText = null;
		const expansionResponse = graphPage.waitForResponse(response => {
			const request = response.request();
			return request.url().endsWith('/graph') &&
				request.postData()?.startsWith('SELECT ?selected ?source ?predicate ?target');
		}, { timeout: 15000 });
		const expansionRequest = graphPage.waitForRequest(request =>
			request.url().endsWith('/graph') && request.postData()?.includes('SELECT ?selected ?source ?predicate ?target'),
		{ timeout: 15000 });
		await badge.locator('rect').click();
		try {
			[request, response] = await Promise.all([expansionRequest, expansionResponse]);
			const query = request.postData() || '';
			responseText = await response.text();
			let responseRows = null;
			try {
				responseRows = JSON.parse(responseText).results?.bindings?.length ?? null;
			} catch {}
			const excluded = query.match(/MINUS \{ VALUES \([^)]*\) \{([\s\S]*?)\} \}/)?.[1] || '';
			expansionEvidence = {
				...expansionEvidence,
				request: {
					url: request.url(),
					method: request.method(),
					requestId: request.headers()['x-rdf4j-request-id'] || null,
					loadedExclusionRows: (excluded.match(/\(/g) || []).length
				},
				response: {
					status: response.status(),
					headers: await response.allHeaders(),
					responseBytes: Buffer.byteLength(responseText),
					responseRows
				},
				responseBytes: Buffer.byteLength(responseText),
				responseRows,
				query
			};
			fs.mkdirSync(EVIDENCE_DIRECTORY, { recursive: true });
			fs.writeFileSync(path.join(EVIDENCE_DIRECTORY, `${evidenceStem}-query.sparql`), query);
			fs.writeFileSync(path.join(EVIDENCE_DIRECTORY, `${evidenceStem}-response.txt`), responseText);
			expansionEvidence.afterResponse = await graphDiagnosticSnapshot(graphPage);
			fs.writeFileSync(path.join(EVIDENCE_DIRECTORY, `${evidenceStem}-diagnostics.json`), JSON.stringify(expansionEvidence, null, 2));
			await expect.poll(async () => {
				const current = aliceNode.locator('.node-more');
				return (await current.count()) === 0 || (await current.first().textContent()) !== before;
			}, { timeout: 15000 }).toBe(true);
			expansionEvidence.settled = await graphDiagnosticSnapshot(graphPage);
			fs.writeFileSync(path.join(EVIDENCE_DIRECTORY, `${evidenceStem}-diagnostics.json`), JSON.stringify(expansionEvidence, null, 2));
		} catch (error) {
			const requestBody = request?.postData() || '';
			const responseBody = responseText ?? (response ? await response.text().catch(() => '') : '');
			if (requestBody) fs.writeFileSync(path.join(EVIDENCE_DIRECTORY, `${evidenceStem}-query.sparql`), requestBody);
			if (response) fs.writeFileSync(path.join(EVIDENCE_DIRECTORY, `${evidenceStem}-response.txt`), responseBody);
			expansionEvidence = {
				...expansionEvidence,
				request: request ? {
					url: request.url(),
					method: request.method(),
					requestId: request.headers()['x-rdf4j-request-id'] || null
				} : null,
				response: response ? {
					status: response.status(),
					headers: await response.allHeaders(),
					responseBytes: Buffer.byteLength(responseBody)
				} : null,
				responseText: responseBody.slice(0, 2000),
				afterFailure: await graphDiagnosticSnapshot(graphPage),
				failure: String(error)
			};
			fs.mkdirSync(EVIDENCE_DIRECTORY, { recursive: true });
			fs.writeFileSync(path.join(EVIDENCE_DIRECTORY, `${evidenceStem}-diagnostics.json`), JSON.stringify(expansionEvidence, null, 2));
			console.error(`Paging did not advance: ${JSON.stringify({
				pageNumber,
				badgeBefore: before,
				badgeAfter: await aliceNode.locator('.node-more text').allTextContents(),
				statsBefore: beforeStats,
				statsAfter: await graph.locator('.graph-stats').textContent(),
				settledStatus: (await graphDiagnosticSnapshot(graphPage)).status,
				visibility: (await graphDiagnosticSnapshot(graphPage)).visibilityEvents,
				queryCountBefore,
				newQueries: traffic.queries.slice(queryCountBefore),
				expansionEvidence: expansionEvidence && {
					...expansionEvidence,
					query: requestBody.slice(0, 1500),
					response: `${Buffer.byteLength(responseBody)} bytes [${path.join(EVIDENCE_DIRECTORY, `${evidenceStem}-response.txt`)}]`
				},
				remainingBadges: await aliceNode.locator('.node-more text').allTextContents()
			})}`);
			throw error;
		}
	}
	const labels = await graph.locator('.graph-node > title').allTextContents();
	const outgoing = labels.filter(label => label.startsWith('Outgoing '));
	const incoming = labels.filter(label => label.startsWith('Incoming '));
	const duplicates = values => Object.entries(values.reduce((counts, value) => {
		counts[value] = (counts[value] || 0) + 1;
		return counts;
	}, {})).filter(([, count]) => count > 1);
	console.info(`Neighbor pagination: ${JSON.stringify({
		nodeGroups: await graph.locator('.graph-node').count(),
		outgoingOccurrences: outgoing.length,
		outgoingUnique: new Set(outgoing).size,
		outgoingDuplicates: duplicates(outgoing),
		incomingOccurrences: incoming.length,
		incomingUnique: new Set(incoming).size,
		incomingDuplicates: duplicates(incoming),
		remainingBadges: await aliceNode.locator('.node-more text').allTextContents(),
		queryCount: traffic.queries.length,
		neighborQueries: traffic.queries.filter(query => query.includes('VALUES ?source') || query.includes('VALUES ?target')).length
	})}`);
	expect(outgoing).toHaveLength(90);
	expect(new Set(outgoing).size).toBe(90);
	expect(incoming).toHaveLength(90);
	expect(new Set(incoming).size).toBe(90);

	const documentPage = await graphPage.context().newPage();
	await addFromExplore(documentPage, `<${DOCUMENT}>`);
	const documentNode = graphNode(graph, 'iri', 'Document');
	await expect(documentNode).toBeAttached({ timeout: 30000 });
	await aliceNode.focus();
	await aliceNode.press('Enter');
	await documentNode.focus();
	await documentNode.press('Shift+Enter');
	await expect(graph.locator('.graph-node.is-selected')).toHaveCount(2);
	await aliceNode.focus();
	await aliceNode.press('Shift+F10');
	const menu = graphPage.getByRole('dialog', { name: /Actions for Alice/ });
	await expect(menu.locator('.menu-header h3')).toHaveText('2 selected nodes');
	await menu.locator('.context-disclosure summary').click();
	await expect.poll(() => traffic.queries.some(query =>
		query.includes('SELECT ?selected ?predicate ?direction') &&
		query.includes(alice.reference) && query.includes(`<${DOCUMENT}>`))).toBe(true);
	await expect.poll(() => traffic.responses.length).toBeGreaterThan(0);
	expect(traffic.responses.every(response => response.status === 200 && response.identity)).toBe(true);
});

test('stored CONSTRUCT results remain expandable while generated template blanks have no remote actions', async ({ page }) => {
	const storedQuery = `CONSTRUCT { ?resource <${NS}storedConstruct> ?resource } WHERE { VALUES ?resource { ${alice.reference} } }`;
	await openQueryPage(page, REPOSITORY_ID);
	await runQuery(page, storedQuery);
	await page.getByRole('button', { name: 'Add the results to the graph' }).click();
	await expect(page.locator('.query-result-add-to-graph')).toContainText('Added to graph');
	await openGraphPage(page);
	const graph = page.locator('.graph-explorer');
	const stored = graphNode(graph, 'blank', 'Alice');
	await expect(stored).toBeAttached({ timeout: 30000 });
	await stored.click();
	let details = page.locator('.node-details');
	await expect(details.getByRole('button', { name: 'Expand', exact: true })).toBeVisible();
	await expect(details.getByRole('link', { name: 'Explore', exact: true })).toBeVisible();

	const syntheticContext = await page.context().browser().newContext();
	const syntheticPage = await syntheticContext.newPage();
	const emptySyntheticGraph = await openGraphPage(syntheticPage);
	await expect(emptySyntheticGraph.locator('.graph-node.blank')).toHaveCount(0);
	await openQueryPage(syntheticPage, REPOSITORY_ID);
	await runQuery(syntheticPage, `CONSTRUCT { [] <${NS}synthetic> "generated" } WHERE {}`);
	await syntheticPage.getByRole('button', { name: 'Add the results to the graph' }).click();
	await expect(syntheticPage.locator('.query-result-add-to-graph')).toContainText('Added to graph');
	await openGraphPage(syntheticPage);
	const syntheticGraph = syntheticPage.locator('.graph-explorer');
	await expect(syntheticGraph.locator('.graph-node.blank')).toHaveCount(1);
	const synthetic = graphNode(syntheticGraph, 'blank', 'generated');
	await expect(synthetic).toBeAttached({ timeout: 30000 });
	await synthetic.click();
	details = syntheticPage.locator('.node-details');
	await expect(details).toBeVisible();
	await expect(details).toContainText('generated');
	await expect(details.getByRole('button', { name: 'Expand', exact: true })).toHaveCount(0);
	await expect(details.getByRole('link', { name: 'Explore', exact: true })).toHaveCount(0);
	await syntheticContext.close();
});
